// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzzed parameter: _nft is the deciding value; other params can be arbitrary wide values
    function testFuzz_property(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // keep feeRate admissible to avoid revert from FeeRateTooHigh in initialize
        // but keep wide: bound to [0,5000]
        _feeRate = uint16(bound(_feeRate, 0, 5000));

        // Call initialize and observe whether nft getter equals the supplied _nft
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            // If initialize reverted, mark as not ok; but reference should not revert for admissible feeRate
            ok = false;
        }

        // If initialize succeeded we can read nft() and assert it equals the provided _nft.
        // Per the reference contract, for any admissible inputs (feeRate <= 5000 and not already initialized) initialize sets nft == _nft.
        // The mutant sets nft = address(this) when _nft == address(0), so this assertion will fail for those inputs on the mutant.
        if (ok) {
            assertTrue(c.nft() == _nft, "nft stored must equal provided _nft");
        } else {
            // If initialize reverted, still assert false to ensure reference must not revert for admissible inputs
            // but keep single assertTrue by asserting a false condition via nft equality to impossible value
            // to satisfy the requirement of exactly one assert in the successful path, we route through ok path above.
            // Here just revert to indicate failing initialization; using assertTrue with false message
            assertTrue(ok, "initialize reverted unexpectedly");
        }
    }
}

