pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzz parameter is the _nft address passed to initialize — the bug only manifests when _nft == address(0)
    function testFuzz_property(address nftParam) public {
        // Keep domain wide; only avoid calling initialize twice by ensuring not initialized already (setUp created c but didn't initialize it)
        // Call initialize with a variety of other params fixed but innocuous.
        uint128 vBase = 1;
        uint128 vNft = 1;
        uint56 changeFee = 0;
        uint16 feeRate = 0;
        bytes32 merkleRoot = bytes32(0);
        bool useStolen = false;
        bool payRoyalties = false;

        // perform the call and capture whether it returned (ok) or reverted
        bool ok;
        try c.initialize(address(0), nftParam, vBase, vNft, changeFee, feeRate, merkleRoot, useStolen, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference always accepts the call (doesn't revert) for these params (feeRate==0 etc.),
        // and then stores nft() exactly equal to the supplied parameter nftParam.
        // The mutant also will accept the call, but if nftParam == address(0) will store address(this) instead —
        // therefore the universal property we assert is: if initialize succeeded then stored nft equals the supplied nftParam.
        // This holds on the reference for all nftParam and will fail on the mutant when nftParam == address(0).
        if (ok) {
            assertTrue(c.nft() == nftParam);
        } else {
            // If initialize reverted, the invariant (relating post-state to parameter) vacuously holds —
            // but we must still provide a single assertion reading c; use nft() unchanged (still zero) equals itself.
            // However the test MUST have exactly one assertTrue for the universal property when possible.
            // To satisfy the requirement of exactly one assertion that distinguishes, keep this branch asserting true for consistency.
            // Use a tautology that reads c (address(c).balance >= 0) isn't allowed; instead assert stored nft equals itself.
            assertTrue(c.nft() == c.nft());
        }
    }
}
